SELECT p.gender, p.age, a.admittime, d.diagnosis_code, s.stay_id, s.length_of_stay, r.risk_score, ntile(5) OVER (ORDER BY r.risk_score) AS quintile, COUNT(DISTINCT CASE WHEN d.diagnosis_code = '30707A' AND s.length_of_stay <= 90 THEN s.subject_id END) AS early_deaths, COUNT(DISTINCT CASE WHEN d.diagnosis_code = '30707A' THEN s.subject_id END) AS all_deaths, AVG(s.length_of_stay) AS avg_length_of_stay FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN stay s ON a.stay_id = s.stay_id JOIN diagnoses_icd d ON s.subject_id = d.subject_id JOIN risk_scores r ON s.subject_id = r.subject_id WHERE p.gender = 'F' AND p.age >= 75 AND p.age <= 80 AND d.diagnosis_code = '30707A' GROUP BY quintile ORDER BY quintile NULLS LAST;